// Generated by scripts/build.mjs — edit src/sw.template.js instead.
// App-shell service worker: the page itself is network-first (so new builds
// show up right away) with the cached shell as the offline fallback; the
// hashed js/css/images are immutable, so they are served cache-first.
const CACHE_VERSION = "87f60ebb5480";
const SHELL_CACHE = `shell-${CACHE_VERSION}`;
const RUNTIME_CACHE = "runtime-v1";
const PRECACHE_URLS = [
  "./",
  "./anniversary-wrapper.html",
  "./assets/browser-AKIEL4OY.js",
  "./assets/chunk-35U5YR53.js",
  "./assets/chunk-DUBGXUAY.js",
  "./assets/chunk-HLDC4GTP.js",
  "./assets/chunk-J6AJKJQZ.js",
  "./assets/chunk-SVIDGI4S.js",
  "./assets/cursor-RP7TFDIH.cur",
  "./assets/html2canvas-O7APVNR3.js",
  "./assets/index.es-D4YYFG3B.js",
  "./assets/island-UQVSYTXN.js",
  "./assets/jspdf.es.min-OCSPEP4B.js",
  "./assets/lib-GQC6TMCM.js",
  "./assets/main-5YZFP4LZ.js",
  "./assets/main-J7UQ63XP.css",
  "./assets/purify.es-TUQRS6UW.js",
  "./assets/quill-IGYLABQZ.js",
  "./assets/theme-glass-8D92DC19.css",
  "./assets/theme-pink-F7288814.css",
  "./assets/theme-purple-23AEB002.css",
  "./assets/theme-red-7FE89D55.css",
  "./cursors/red.cur",
  "./discord-wide.png",
  "./icons/badge-96.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./index.html",
  "./site.webmanifest"
];
const RUNTIME_HOSTS = new Set(["fonts.googleapis.com", "fonts.gstatic.com"]);
const PHOTO_CACHE = "photos-v1";
const PHOTO_CACHE_LIMIT = 60;
// never rewritten in place: a new picture gets a new address
const WIDGET_PHOTO_PATH = /^\/storage\/v1\/object\/public\/(?:profile-pictures\/|[^/]+\/[^/]+\/widget-photos\/)/;

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches
      .open(SHELL_CACHE)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key.startsWith("shell-") && key !== SHELL_CACHE)
            .map((key) => caches.delete(key)),
        ),
      )
      .then(() => self.clients.claim()),
  );
});

async function networkFirstPage(request) {
  const cache = await caches.open(SHELL_CACHE);
  try {
    const response = await fetch(request);
    if (response.ok) cache.put("./", response.clone());
    return response;
  } catch {
    return (
      (await cache.match("./")) ||
      (await cache.match("./index.html")) ||
      new Response("offline ♡", { status: 503, headers: { "Content-Type": "text/plain; charset=utf-8" } })
    );
  }
}

async function cacheFirst(request, cacheName) {
  const cached = await caches.match(request);
  if (cached) return cached;
  const response = await fetch(request);
  if (response.ok || response.type === "opaque") {
    const cache = await caches.open(cacheName);
    cache.put(request, response.clone());
  }
  return response;
}

// A pinned photo's address never changes (every upload gets a new one), so a
// copy kept on the device is always right and opens instantly.
async function cachedWidgetPhoto(request) {
  const cache = await caches.open(PHOTO_CACHE);
  const cached = await cache.match(request.url);
  if (cached) return cached;
  try {
    const response = await fetch(request.url, { mode: "cors", credentials: "omit" });
    if (response.ok) {
      await cache.put(request.url, response.clone());
      const keys = await cache.keys();
      await Promise.all(keys.slice(0, -PHOTO_CACHE_LIMIT).map((key) => cache.delete(key)));
    }
    return response;
  } catch {
    return fetch(request);
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  if (request.mode === "navigate" && url.origin === self.location.origin) {
    // Only the diary page itself gets the shell fallback.
    if (/\/(index\.html)?$/.test(url.pathname)) {
      event.respondWith(networkFirstPage(request));
    }
    return;
  }

  if (url.origin === self.location.origin) {
    event.respondWith(cacheFirst(request, SHELL_CACHE));
    return;
  }

  if (WIDGET_PHOTO_PATH.test(url.pathname)) {
    event.respondWith(cachedWidgetPhoto(request));
    return;
  }

  // Google Fonts: css + font files are safe to keep for offline use.
  // Supabase, GIPHY, YouTube etc. always go straight to the network.
  if (RUNTIME_HOSTS.has(url.hostname)) {
    event.respondWith(cacheFirst(request, RUNTIME_CACHE));
  }
});

// ---------------------------------------------------------------------------
// Push notifications (sent by the send-push Supabase function)
// ---------------------------------------------------------------------------

self.addEventListener("push", (event) => {
  let payload = {};
  try {
    payload = event.data ? event.data.json() : {};
  } catch {
    payload = { body: event.data ? event.data.text() : "" };
  }

  const title = payload.title || "TOTO & DODO";
  const options = {
    body: payload.body || "",
    icon: "./icons/icon-192.png",
    badge: "./icons/badge-96.png",
    tag: payload.tag || undefined,
    renotify: Boolean(payload.tag),
    timestamp: Date.now(),
    data: {
      type: payload.type || "",
      postId: payload.postId || "",
      widgetId: payload.widgetId || "",
      commentId: payload.commentId || "",
      openComments: Boolean(payload.openComments),
    },
  };

  event.waitUntil(
    Promise.all([
      self.registration.showNotification(title, options),
      // a dot on the app icon until the diary is opened again
      self.navigator.setAppBadge ? self.navigator.setAppBadge().catch(() => {}) : null,
    ]),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const target = event.notification.data || {};

  event.waitUntil(
    (async () => {
      const windows = await self.clients.matchAll({ type: "window", includeUncontrolled: true });
      // only the diary itself listens for "push-open", not the gift page
      const scope = self.registration.scope;
      const client = windows.find((item) => {
        const page = item.url.split(/[?#]/)[0];
        return page === scope || page === `${scope}index.html`;
      });
      if (client) {
        await client.focus();
        client.postMessage({ ...target, type: "push-open" });
        return;
      }

      const url = new URL("./", self.registration.scope);
      if (target.postId) url.searchParams.set("push_post", target.postId);
      if (target.widgetId) url.searchParams.set("push_widget", target.widgetId);
      if (target.openComments) url.searchParams.set("push_comments", "1");
      if (target.commentId) url.searchParams.set("push_comment", target.commentId);
      await self.clients.openWindow(url.href);
    })(),
  );
});

// The browser rotated this device's push keys: tell the open app to re-register.
self.addEventListener("pushsubscriptionchange", (event) => {
  event.waitUntil(
    self.clients.matchAll({ type: "window" }).then((windows) => {
      windows.forEach((client) => client.postMessage({ type: "push-resubscribe" }));
    }),
  );
});
